import re
import requests
import json
import base64

def fetch_video_info(video_id):
    """Get video data using YouTube API via invidious instances"""
    invidious_instances = [
        "https://invidious.snopyta.org",
        "https://yewtu.be",
        "https://invidious.kavin.rocks"
    ]

    for instance in invidious_instances:
        try:
            url = f"{instance}/api/v1/videos/{video_id}"
            print(f"Trying to fetch video info from {url}")
            response = requests.get(url, timeout=10)
            if response.status_code == 200:
                return response.json()
        except Exception as e:
            print(f"Error with {instance}: {e}")

    return None

def extract_comments(video_id):
    """Extract comments from the video"""
    invidious_instances = [
        "https://invidious.snopyta.org",
        "https://yewtu.be",
        "https://invidious.kavin.rocks"
    ]

    for instance in invidious_instances:
        try:
            url = f"{instance}/api/v1/comments/{video_id}"
            print(f"Trying to fetch comments from {url}")
            response = requests.get(url, timeout=10)
            if response.status_code == 200:
                return response.json()
        except Exception as e:
            print(f"Error with {instance}: {e}")

    return None

def fetch_captions(video_id):
    """Get captions/subtitles from the video"""
    invidious_instances = [
        "https://invidious.snopyta.org",
        "https://yewtu.be",
        "https://invidious.kavin.rocks"
    ]

    for instance in invidious_instances:
        try:
            # First get available caption tracks
            info_url = f"{instance}/api/v1/videos/{video_id}"
            info_response = requests.get(info_url, timeout=10)
            if info_response.status_code == 200:
                info = info_response.json()
                if 'captions' in info and info['captions']:
                    for caption in info['captions']:
                        caption_url = f"{instance}/api/v1/captions/{video_id}?label={caption['label']}"
                        print(f"Trying to fetch captions from {caption_url}")
                        caption_response = requests.get(caption_url, timeout=10)
                        if caption_response.status_code == 200:
                            return caption_response.json()
        except Exception as e:
            print(f"Error with {instance}: {e}")

    return None

def fetch_youtube_page(video_id):
    """Fetch the YouTube page directly to check for hidden content"""
    url = f"https://www.youtube.com/watch?v={video_id}"
    try:
        print(f"Fetching YouTube page: {url}")
        response = requests.get(url, timeout=10)
        return response.text
    except Exception as e:
        print(f"Error fetching YouTube page: {e}")
        return None

def check_description_for_flag(video_info):
    """Check video description for flag"""
    if video_info and 'description' in video_info:
        description = video_info['description']
        print("Video description:")
        print(description)

        # Look for the flag pattern
        flag_pattern = r'csawctf\{[^}]*\}'
        matches = re.findall(flag_pattern, description)
        if matches:
            print(f"Found potential flag in description: {matches[0]}")
            return matches[0]

        # Look for base64 encoded strings
        b64_pattern = r'[A-Za-z0-9+/=]{20,}'
        matches = re.findall(b64_pattern, description)
        for match in matches:
            try:
                decoded = base64.b64decode(match).decode('utf-8')
                print(f"Decoded base64: {decoded}")
                flag_match = re.search(flag_pattern, decoded)
                if flag_match:
                    print(f"Found flag in decoded base64: {flag_match.group(0)}")
                    return flag_match.group(0)
            except:
                pass

    return None

