    """Check video comments for flag"""
    if not comments:
        return None

    flag_pattern = r'csawctf\{[^}]*\}'

    for comment in comments.get('comments', []):
        if 'content' in comment:
            content = comment['content']
            matches = re.findall(flag_pattern, content)
            if matches:
                print(f"Found potential flag in comment: {matches[0]}")
                return matches[0]

            # Also check for base64 encoded strings
            b64_pattern = r'[A-Za-z0-9+/=]{20,}'
            matches = re.findall(b64_pattern, content)
            for match in matches:
                try:
                    decoded = base64.b64decode(match).decode('utf-8')
                    print(f"Decoded base64 from comment: {decoded}")
                    flag_match = re.search(flag_pattern, decoded)
                    if flag_match:
                        print(f"Found flag in decoded base64 from comment: {flag_match.group(0)}")
                        return flag_match.group(0)
                except:
                    pass

    return None

