        for match in matches:
            try:
                decoded = base64.b64decode(match).decode('utf-8')
                print(f"Decoded base64 from captions: {decoded}")
                flag_match = re.search(flag_pattern, decoded)
                if flag_match:
                    print(f"Found flag in decoded base64 from captions: {flag_match.group(0)}")
                    return flag_match.group(0)
            except:
                pass

    return None

def check_html_for_flag(html):
    """Check YouTube page HTML for flag"""
    if not html:
        return None

    flag_pattern = r'csawctf\{[^}]*\}'
    matches = re.findall(flag_pattern, html)
    if matches:
        print(f"Found potential flag in HTML: {matches[0]}")
        return matches[0]

    # Look for hidden data in meta tags
    meta_pattern = r'<meta[^>]*content=["\']([^"\']*)["\'][^>]*>'
    matches = re.findall(meta_pattern, html)
    for match in matches:
        flag_match = re.search(flag_pattern, match)
        if flag_match:
            print(f"Found flag in meta tag: {flag_match.group(0)}")
            return flag_match.group(0)

    # Look for hidden comments in HTML
    comment_pattern = r'<!--(.*?)-->'
    matches = re.findall(comment_pattern, html, re.DOTALL)
    for match in matches:
        flag_match = re.search(flag_pattern, match)
        if flag_match:
            print(f"Found flag in HTML comment: {flag_match.group(0)}")
            return flag_match.group(0)

        # Also check for base64 encoded strings
        b64_pattern = r'[A-Za-z0-9+/=]{20,}'
        b64_matches = re.findall(b64_pattern, match)
        for b64_match in b64_matches:
            try:
                decoded = base64.b64decode(b64_match).decode('utf-8')
                print(f"Decoded base64 from HTML comment: {decoded}")
                flag_match = re.search(flag_pattern, decoded)
                if flag_match:
                    print(f"Found flag in decoded base64 from HTML comment: {flag_match.group(0)}")
                    return flag_match.group(0)
            except:
                pass

    # Check for scripts that might contain the flag
    script_pattern = r'<script[^>]*>(.*?)</script>'
    matches = re.findall(script_pattern, html, re.DOTALL)
    for match in matches:
        flag_match = re.search(flag_pattern, match)
        if flag_match:
            print(f"Found flag in script: {flag_match.group(0)}")
            return flag_match.group(0)

    # Check for "Urkel" references
    urkel_pattern = r'([^.]*Urkel[^.]*\.)'
    matches = re.findall(urkel_pattern, html)
    for match in matches:
        print(f"Found Urkel reference: {match}")

    return None

